{"code": "import requests
import json

orcid_ids = [
    ("Manuela Nagel", "0000-0003-0396-0333"),
    ("Tatjana Gavrilenko", "0000-0002-2605-6569"),
    ("John Bamberg", "0000-0001-6102-7846"),
    ("David Ellis", "0000-0002-0209-2784"),
    ("Peter Giovannini", "0000-0002-1053-2030"),
]

results = {}

for name, orcid in orcid_ids:
    url = f"https://pub.orcid.org/v3.0/{orcid}/works?rows=0"
    headers = {"Accept": "application/json"}
    try:
        resp = requests.get(url, headers=headers, timeout=60)
        data = resp.json()
        groups = data.get('group', [])
        total_works = len(groups)
        pre_2020_count = 0

        for group in groups:
            work_summaries = group.get('work-summary', [])
            for ws in work_summaries:
                pub_date = ws.get('publication-date')
                if pub_date and isinstance(pub_date, dict):
                    year_str = pub_date.get('year', {}).get('value', '')
                    if year_str:
                        year = int(year_str)
                        if year < 2020:
                            pre_2020_count += 1

        results[name] = {
            'orcid': orcid,
            'total_works': total_works,
            'pre_2020_count': pre_2020_count
        }
        print(f"{name}: total={total_works}, pre-2020={pre_2020_count}")
    except Exception as e:
        print(f"{name}: Error - {e}")

